"""Seasonal-normalized Ridge with month-specific lag coefficients.

Transform: b(s,m) = mean flow of station s in calendar month m over train;
a(s,t) = (x - b(s,m(t))) / sc(s), sc(s) robust scale (MAD) of a over train.
Model: separate Ridge per lead h=1..3 on a(s,T+h); direct, not recursive.
Feature layout (both modes):
  [intercept,
   a-lags 1..L (global coefficients),
   (optional) month-lag block: 12 months x lags 1..3, a(T-k) kept only for
   the calendar month of origin T,
   (optional) month one-hot (12),
   (shared only) station one-hot (9)]
Prediction: pred = b(s,m(T+h)) + bias * a_hat * sc(s), clipped at 0.
"""
import numpy as np
import pandas as pd

STATIONS = ["hongjiadu", "dongfeng", "suofengying", "wujiangdu", "goupitan",
            "silin", "shatuo", "dahuashui", "geliqiao"]

# Step 3: top structure (station, L=6, month_lag on, no offset); bias in {0.9,0.95,1.0},
# year_from in {1951,1990}, alpha in {1,5} (refit for larger feature set).
candidates = [
    {"model": "station", "alpha": 1.0, "L": 6, "month_lag": True, "month_offset": False, "bias": 1.0, "year_from": 1951, "seed": 0},
    {"model": "station", "alpha": 1.0, "L": 6, "month_lag": True, "month_offset": False, "bias": 0.95, "year_from": 1951, "seed": 0},
    {"model": "station", "alpha": 1.0, "L": 6, "month_lag": True, "month_offset": False, "bias": 0.9, "year_from": 1951, "seed": 0},
    {"model": "station", "alpha": 1.0, "L": 6, "month_lag": True, "month_offset": False, "bias": 1.0, "year_from": 1990, "seed": 0},
    {"model": "station", "alpha": 1.0, "L": 6, "month_lag": True, "month_offset": False, "bias": 0.95, "year_from": 1990, "seed": 0},
    {"model": "station", "alpha": 5.0, "L": 6, "month_lag": True, "month_offset": False, "bias": 1.0, "year_from": 1951, "seed": 0},
    {"model": "station", "alpha": 5.0, "L": 6, "month_lag": True, "month_offset": False, "bias": 0.95, "year_from": 1951, "seed": 0},
    {"model": "station", "alpha": 5.0, "L": 6, "month_lag": True, "month_offset": False, "bias": 0.9, "year_from": 1951, "seed": 0},
]


def _mi(m):
    return int(m[:4]) * 12 + int(m[5:7]) - 1


def _solve_ridge(X, y, alpha):
    A = X.T @ X + alpha * np.eye(X.shape[1])
    A[0, 0] -= alpha  # do not penalize intercept
    return np.linalg.solve(A, X.T @ y)


def _seasonal(train_data, p):
    df = train_data.reset_index(drop=True)
    cols = list(df.columns[1:])
    tdf = df[df.month.str[:4].astype(int) >= p["year_from"]].reset_index(drop=True)
    mi = np.array([_mi(m) for m in tdf.month])
    x = tdf[cols].to_numpy(dtype=float)
    mcal = mi % 12
    S = x.shape[1]
    b = np.array([x[mcal == m].mean(axis=0) for m in range(12)])
    a = (x - b[mcal])
    sc = np.empty(S)
    for s in range(S):
        col = a[:, s]
        mad = np.median(np.abs(col - np.median(col))) * 1.4826
        if not np.isfinite(mad) or mad < 1e-9:
            iqr = np.percentile(col, 75) - np.percentile(col, 25)
            mad = iqr / 1.349 if iqr > 1e-9 else 1.0
        sc[s] = mad
    a = a / sc
    return mi, mcal, a, b, sc, S


def fit(train_data, num_months, candidates):
    state = {"candidates": list(candidates), "models": []}
    for p in candidates:
        mi, mcal, a, b, sc, S = _seasonal(train_data, p)
        n = a.shape[0]
        L = p["L"]
        month_lag = p["month_lag"]
        month_offset = p["month_offset"]
        shared = p["model"] == "shared"
        first = max(L, 11)  # origins not earlier than 1952-04 (index 11)
        origins = np.arange(first, n - num_months)
        if len(origins) == 0:
            raise ValueError("not enough training data")
        total = 1 + L + (36 if month_lag else 0) + (12 if month_offset else 0) + (9 if shared else 0)
        models_h = {}
        for h in range(1, num_months + 1):
            if shared:
                Xs, ys = [], []
                for T in origins:
                    m = int(mcal[T])
                    lags_all = a[T - 1:T - L - 1:-1, :]  # (L, S)
                    for s in range(S):
                        row = [1.0] + [float(v) for v in lags_all[:, s]]
                        if month_lag:
                            for k in range(1, 4):
                                for mm in range(12):
                                    row.append(float(lags_all[k - 1, s]) if mm == m else 0.0)
                        if month_offset:
                            for mm in range(12):
                                row.append(1.0 if mm == m else 0.0)
                        for ss in range(S):
                            row.append(1.0 if ss == s else 0.0)
                        Xs.append(row)
                        ys.append(a[T + h, s])
                Xs = np.array(Xs)
                w = _solve_ridge(Xs, ys, p["alpha"])
                assert Xs.shape[1] == total
                models_h[h] = w
            else:
                ws = []
                for s in range(S):
                    Xs = np.zeros((len(origins), total))
                    Ys = np.zeros(len(origins))
                    for i, T in enumerate(origins):
                        m = int(mcal[T])
                        lags = [float(a[T - k, s]) for k in range(1, L + 1)]
                        row = [1.0] + lags
                        if month_lag:
                            for k in range(1, 4):
                                for mm in range(12):
                                    row.append(lags[k - 1] if mm == m else 0.0)
                        if month_offset:
                            for mm in range(12):
                                row.append(1.0 if mm == m else 0.0)
                        Xs[i] = row
                        Ys[i] = a[T + h, s]
                    ws.append(_solve_ridge(Xs, Ys, p["alpha"]))
                models_h[h] = ws
        state["models"].append({
            "b": b, "sc": sc, "a": a, "models": models_h, "S": S,
            "L": L, "month_lag": month_lag, "month_offset": month_offset,
            "shared": shared,
        })
    return state


def predict(state, history_data, target_months):
    df = history_data.reset_index(drop=True)
    cols = list(df.columns[1:])
    mi = np.array([_mi(m) for m in df.month])
    x = df[cols].to_numpy(dtype=float)
    mcal = mi % 12
    T = len(mi) - 1
    mT = int(mcal[T])
    results = []
    for idx, info in enumerate(state["models"]):
        p = state["candidates"][idx]
        b, sc = info["b"], info["sc"]
        S, L = info["S"], info["L"]
        month_lag, month_offset, shared = info["month_lag"], info["month_offset"], info["shared"]
        a = (x - b[mcal]) / sc
        a_lags = [a[T - k] for k in range(1, L + 1)]
        preds = np.zeros((len(target_months), S))
        for h in range(1, len(target_months) + 1):
            w = info["models"][h]
            tgt_month = (mi[T] + h) % 12
            if shared:
                for s in range(S):
                    lags = [float(a[T - k, s]) for k in range(1, L + 1)]
                    row = [1.0] + lags
                    if month_lag:
                        for k in range(1, 4):
                            for mm in range(12):
                                row.append(lags[k - 1] if mm == mT else 0.0)
                    if month_offset:
                        for mm in range(12):
                            row.append(1.0 if mm == mT else 0.0)
                    for ss in range(S):
                        row.append(1.0 if ss == s else 0.0)
                    ah = float(np.array(row) @ w)
                    preds[h - 1, s] = b[tgt_month, s] + p["bias"] * ah * sc[s]
            else:
                for s in range(S):
                    lags = [float(a[T - k, s]) for k in range(1, L + 1)]
                    row = [1.0] + lags
                    if month_lag:
                        for k in range(1, 4):
                            for mm in range(12):
                                row.append(lags[k - 1] if mm == mT else 0.0)
                    if month_offset:
                        for mm in range(12):
                            row.append(1.0 if mm == mT else 0.0)
                    ah = float(np.array(row) @ w[s])
                    preds[h - 1, s] = b[tgt_month, s] + p["bias"] * ah * sc[s]
        results.append(np.maximum(preds, 0.0))
    return results

